-- OfferLab R9 acceptance dataset. Test environment only.
SET NAMES utf8mb4;
SET @batch_code = 'R9-20260817-ACCEPTANCE';

CREATE TABLE IF NOT EXISTS t_acceptance_data_batch_item (
    batch_code VARCHAR(64) NOT NULL,
    entity_type VARCHAR(32) NOT NULL,
    entity_id BIGINT NOT NULL,
    before_json JSON NULL,
    create_time DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
    PRIMARY KEY (batch_code, entity_type, entity_id),
    KEY idx_acceptance_batch_entity (entity_type, entity_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='Test-environment acceptance data audit';

DELIMITER $$
DROP PROCEDURE IF EXISTS r9_acceptance_assert_safe$$
CREATE PROCEDURE r9_acceptance_assert_safe()
BEGIN
    IF EXISTS (
        SELECT 1
        FROM (
            SELECT 'USER' AS entity_type, id FROM t_user_account
             WHERE id BETWEEN 995000000000000001 AND 995000000000000005
            UNION ALL
            SELECT 'POST', id FROM t_post_main
             WHERE id BETWEEN 995100000000000001 AND 995100000000000023
            UNION ALL
            SELECT 'COMMENT', id FROM t_int_comment
             WHERE id BETWEEN 995120000000000001 AND 995120000000000029
            UNION ALL
            SELECT 'QUESTION', id FROM t_interview_question
             WHERE id BETWEEN 995200000000000001 AND 995200000000000008
            UNION ALL
            SELECT 'OPERATION_SLOT', id FROM t_operation_slot
             WHERE id BETWEEN 995300000000000001 AND 995300000000000002
        ) existing
        WHERE NOT EXISTS (
            SELECT 1
            FROM t_acceptance_data_batch_item audit
            WHERE audit.batch_code = @batch_code
              AND audit.entity_type = existing.entity_type
              AND audit.entity_id = existing.id
        )
    ) THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'R9 fixed ID range contains non-batch data';
    END IF;

    IF EXISTS (
        SELECT 1
        FROM t_user_account
        WHERE is_deleted = 0
          AND email IN (
              'lin.cheng@community.invalid',
              'zhou.yuzhou@community.invalid',
              'su.yao@community.invalid',
              'chen.he@community.invalid',
              'gu.yuanchuan@community.invalid'
          )
          AND id NOT BETWEEN 995000000000000001 AND 995000000000000005
    ) THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'R9 author email conflicts with existing data';
    END IF;

    IF EXISTS (
        SELECT 1
        FROM t_operation_slot
        WHERE is_deleted = 0
          AND slot_code IN ('HOME_FEATURED', 'DISCOVERY_FEATURED_TOPICS')
          AND id NOT BETWEEN 995300000000000001 AND 995300000000000002
    ) THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'R9 operation slot code conflicts with existing data';
    END IF;
END$$
CALL r9_acceptance_assert_safe()$$
DROP PROCEDURE r9_acceptance_assert_safe$$
