WHERE id = 995100000000000016;

UPDATE t_post_main
SET content = IF(
    LOCATE('## 演练记录应该怎样留下证据', content) > 0,
    content,
    CONCAT(
        content,
        '\n\n## 演练记录应该怎样留下证据\n\n',
        '每次演练都要记录信号到达时间、实例从就绪列表移除的时间、入口停止接收的时间、队列长度变化、最后一个任务完成时间和进程退出时间。只写“演练通过”无法支持后续比较，也无法判断慢在平台摘流、业务入口还是任务本身。记录应能按实例和发布批次关联，但公开页面不展示内部机器标识。\n\n',
        '异常场景至少包括：外部依赖在宽限期内持续超时、任务线程忽略中断、重放记录写入失败、同一业务键重复到达、新旧版本同时消费以及第二次终止信号提前到达。每个场景都要明确预期状态，特别是已经产生外部副作用但本地状态尚未完成时，不能笼统地再次执行整个任务。\n\n',
        '发布完成后还要做总量对账。接收任务数应等于成功数、明确失败数、转入重放数和仍在处理中数量之和；重放完成后再次核对最终业务结果，确认没有重复写入。只有当运行指标、业务结果和恢复记录三者一致，演练才算真正完成。'
    )
)
WHERE id = 995100000000000001;

UPDATE t_post_main
SET content = IF(
    LOCATE('## 如何让四层系统在忙碌阶段仍然运行', content) > 0,
    content,
    CONCAT(
        content,
        '\n\n## 如何让四层系统在忙碌阶段仍然运行\n\n',
        '时间紧张时，我不会同时缩减四层，而是先缩小输入范围。主教材每周只推进一个小节，练习保留一个最小任务，反馈只找最影响理解的一处，复习只处理近期真实出错的问题。这样学习速度会变慢，但闭环仍在；如果只保留输入，表面进度反而最容易失真。\n\n',
        '为了避免计划无限膨胀，每个主题开始前先写结束条件。例如“能够解释线程池参数并完成一次容量估算”，比“学完并发”更容易判断。结束条件达到后先进入使用和复习，不因为还有更多资料就推迟收尾。新资料只有在暴露具体缺口时才加入，而不是看到推荐就改变路线。\n\n',
        '每月复盘时查看四类证据：自己能够独立解释的问题、完成过的练习、收到并处理的反馈、隔一段时间仍能解决的新情境。收藏数量和观看时长不作为核心指标。这样即使学习主题变化，仍能比较方法是否有效，也更容易发现到底是哪一层长期缺失。'
    )
)
WHERE id = 995100000000000011;

UPDATE t_post_main
SET content = IF(
    LOCATE('## 金额确定后的维护规则', content) > 0,
    content,
    CONCAT(
        content,
        '\n\n## 金额确定后的维护规则\n\n',
        '应急资金达到目标后，我每季度只检查三件事：底线支出是否变化、可快速取用的渠道是否仍然可靠、家庭责任是否增加。工资增长并不自动意味着目标金额同比增长，真正影响金额的是必要支出和风险暴露。相反，如果搬家、健康或工作状态改变，就需要重新计算，而不是继续沿用旧数字。\n\n',
        '账户之间的转移也要保持简单。第一层不参与需要频繁判断的操作，不因为短期收益差异来回移动；第二层必须写清到账时间和可能的限制。任何产品只要规则难以向家人说明，或在压力情境下可能无法及时使用，就不承担应急角色。收益是次要结果，确定性和可用性才是主要目的。\n\n',
        '真正使用时保留支出原因、金额、剩余覆盖月数和补回计划，但不把突发事件变成自责。记录的目的是确认原来的风险判断是否合理，并帮助下一次调整保险、预算或家庭分工。恢复完成后再回到长期计划，避免一边缺少缓冲，一边继续承担不必要的波动。'
    )
)
WHERE id = 995100000000000020;

UPDATE t_post_main
SET content = IF(
    LOCATE('## 从一次演练走向持续发布门禁', content) > 0,
    content,
    CONCAT(
        content,
        '\n\n## 从一次演练走向持续发布门禁\n\n',
        '演练结论最终要进入发布门禁：关键入口必须支持停止接收，核心任务必须有幂等与重放方案，监控必须能在同一时间线中解释摘流、存量处理和退出。任何一项缺失，都应明确阻断发布或缩小发布范围，而不是依赖值班人员临场判断。门禁规则也要定期回看，防止新增入口绕过停机协议。'
    )
)
WHERE id = 995100000000000001;

UPDATE t_post_main
SET content = IF(
    LOCATE('## 判断学习系统是否正在失效', content) > 0,
    content,
    CONCAT(
        content,
        '\n\n## 判断学习系统是否正在失效\n\n',
        '当待学列表持续增长、练习总被推迟、相同错误反复出现或笔记无法帮助解决新问题时，系统已经失效。此时先暂停新增输入，选一个最近真实遇到的问题走完解释、练习、反馈和复习，再决定是否恢复原计划。缩小范围不是退步，而是让反馈重新进入循环。'
    )
)
WHERE id = 995100000000000011;

UPDATE t_post_main
SET content = IF(
    LOCATE('## 一次只修复一个最明显的断点', content) > 0,
    content,
    CONCAT(
        content,
        '\n\n## 一次只修复一个最明显的断点\n\n',
        '如果输入已经足够而练习总是缺席，就先把下一次阅读改成一次可提交的练习；如果练习很多却没有反馈，就固定找一位同伴检查假设和表达；如果每次都在相同位置出错，就把错误整理成对比卡并安排回访。一次只修复一个断点，才能判断改变是否真正有效。'
    )
)
WHERE id = 995100000000000011;

UPDATE t_post_main
