INSERT INTO t_int_comment
    (id, post_id, post_author_id, author_id, root_id, parent_id, reply_to_uid,
     content, like_count, helpful_count, comment_status, create_time, update_time, is_deleted)
VALUES
    (995120000000000001, 995100000000000001, 995000000000000001, 995000000000000002, 0, 0, NULL, '把就绪检查先摘流量这一点讲得很清楚。我们之前只依赖容器退出信号，确实会让最后一批请求变得不可解释。', 18, 7, 1, NOW(3) - INTERVAL 22 DAY, NOW(3), 0),
    (995120000000000002, 995100000000000001, 995000000000000001, 995000000000000003, 0, 0, NULL, '宽限期参考任务耗时分位数比固定写三十秒更合理。希望后续能补一段如何选取观察窗口。', 14, 6, 1, NOW(3) - INTERVAL 21 DAY, NOW(3), 0),
    (995120000000000003, 995100000000000001, 995000000000000001, 995000000000000004, 0, 0, NULL, '如果任务里还有上传文件这类长操作，你们会在入口关闭后继续允许已有上传完成吗？', 9, 3, 1, NOW(3) - INTERVAL 20 DAY, NOW(3), 0),
    (995120000000000004, 995100000000000001, 995000000000000001, 995000000000000005, 0, 0, NULL, '任务总数守恒是很好的验收标准，比只看进程是否正常退出可靠得多。', 12, 5, 1, NOW(3) - INTERVAL 19 DAY, NOW(3), 0),
    (995120000000000005, 995100000000000001, 995000000000000001, 995000000000000002, 0, 0, NULL, '建议把第二次终止信号也纳入演练，很多运行平台会在宽限期结束后直接强制结束。', 11, 4, 1, NOW(3) - INTERVAL 18 DAY, NOW(3), 0),
    (995120000000000006, 995100000000000001, 995000000000000001, 995000000000000003, 0, 0, NULL, '重放记录里除了业务键和阶段，是否还会保存原始请求版本？版本变化后重放可能产生不同结果。', 10, 4, 1, NOW(3) - INTERVAL 17 DAY, NOW(3), 0),
    (995120000000000007, 995100000000000001, 995000000000000001, 995000000000000004, 0, 0, NULL, '对定时任务的处理很有启发。我们遇到过停机时任务刚被调度，下一实例又重复调度一次。', 8, 3, 1, NOW(3) - INTERVAL 16 DAY, NOW(3), 0),
    (995120000000000008, 995100000000000001, 995000000000000001, 995000000000000005, 0, 0, NULL, '这里的入口开关如果和注册中心摘除同时发生，顺序是否需要固定？', 7, 2, 1, NOW(3) - INTERVAL 15 DAY, NOW(3), 0),
    (995120000000000009, 995100000000000001, 995000000000000001, 995000000000000002, 0, 0, NULL, '我会再加一个指标：进入停机阶段后仍新增的任务数，用来发现遗漏的入口。', 13, 5, 1, NOW(3) - INTERVAL 14 DAY, NOW(3), 0),
    (995120000000000010, 995100000000000001, 995000000000000001, 995000000000000003, 0, 0, NULL, '同意不要把 shutdown hook 当作全部方案，真正困难的是业务状态怎样恢复。', 9, 3, 1, NOW(3) - INTERVAL 13 DAY, NOW(3), 0),
    (995120000000000011, 995100000000000001, 995000000000000001, 995000000000000004, 0, 0, NULL, '这篇适合和消息消费的重平衡流程放在一起看，两边都涉及停止接收和处理存量。', 6, 2, 1, NOW(3) - INTERVAL 12 DAY, NOW(3), 0),
    (995120000000000012, 995100000000000001, 995000000000000001, 995000000000000005, 0, 0, NULL, '外部调用已经成功、本地状态还没落库时，补偿策略需要单独设计，不能只靠重试原任务。', 15, 6, 1, NOW(3) - INTERVAL 11 DAY, NOW(3), 0),
    (995120000000000013, 995100000000000001, 995000000000000001, 995000000000000002, 0, 0, NULL, '我们把最老任务等待时间加到发布看板后，确实更容易判断是否该继续等待。', 8, 3, 1, NOW(3) - INTERVAL 10 DAY, NOW(3), 0),
    (995120000000000014, 995100000000000001, 995000000000000001, 995000000000000003, 0, 0, NULL, '宽限期里的日志最好带同一次停机的关联标识，否则多实例同时发布时很难串起来。', 10, 4, 1, NOW(3) - INTERVAL 9 DAY, NOW(3), 0),
    (995120000000000015, 995100000000000001, 995000000000000001, 995000000000000004, 0, 0, NULL, '如果线程被业务代码忽略中断信号，最终还是只能强制结束，所以任务本身也要遵守中断契约。', 12, 5, 1, NOW(3) - INTERVAL 8 DAY, NOW(3), 0),
    (995120000000000016, 995100000000000001, 995000000000000001, 995000000000000005, 0, 0, NULL, '把未完成任务写入可重放记录时，写入动作本身失败要怎样处理？这一层也需要最小兜底。', 7, 2, 1, NOW(3) - INTERVAL 7 DAY, NOW(3), 0),
    (995120000000000017, 995100000000000001, 995000000000000001, 995000000000000002, 0, 0, NULL, '文章里的验收项可以直接变成发布演练清单，尤其是摘流时间和任务守恒。', 11, 4, 1, NOW(3) - INTERVAL 6 DAY, NOW(3), 0),
    (995120000000000018, 995100000000000001, 995000000000000001, 995000000000000003, 0, 0, NULL, '对于无状态短任务可以简单一些，但只要带外部副作用，确实应该先定义重放语义。', 6, 2, 1, NOW(3) - INTERVAL 5 DAY, NOW(3), 0),
    (995120000000000019, 995100000000000001, 995000000000000001, 995000000000000004, 0, 0, NULL, '滚动发布期间新旧版本同时存在时，任务载荷的兼容性也值得加入演练。', 9, 3, 1, NOW(3) - INTERVAL 4 DAY, NOW(3), 0),
    (995120000000000020, 995100000000000001, 995000000000000001, 995000000000000005, 0, 0, NULL, '我们后来把停机状态暴露给内部诊断页，但普通用户只看到服务正在切换，避免泄露实现细节。', 8, 3, 1, NOW(3) - INTERVAL 3 DAY, NOW(3), 0),
    (995120000000000021, 995100000000000001, 995000000000000001, 995000000000000002, 0, 0, NULL, '任务队列很短时也要保留最小等待窗口，否则瞬时波动会让发布结果不稳定。', 5, 2, 1, NOW(3) - INTERVAL 2 DAY, NOW(3), 0),
    (995120000000000022, 995100000000000001, 995000000000000001, 995000000000000003, 0, 0, NULL, '建议补充 executor awaitTermination 返回 false 之后的处理分支，很多示例到这里就结束了。', 7, 3, 1, NOW(3) - INTERVAL 36 HOUR, NOW(3), 0),
    (995120000000000023, 995100000000000001, 995000000000000001, 995000000000000004, 0, 0, NULL, '这套流程也适合批处理任务，只是存量统计和重放粒度会不一样。', 4, 1, 1, NOW(3) - INTERVAL 30 HOUR, NOW(3), 0),
    (995120000000000024, 995100000000000001, 995000000000000001, 995000000000000005, 0, 0, NULL, '如果使用虚拟线程，停机边界仍然存在，只是并发数量和观察指标需要调整。', 6, 2, 1, NOW(3) - INTERVAL 24 HOUR, NOW(3), 0),
    (995120000000000025, 995100000000000001, 995000000000000001, 995000000000000002, 0, 0, NULL, '最终能回答每个任务去了哪里，这句话很重要，也是用户信任的基础。', 10, 4, 1, NOW(3) - INTERVAL 18 HOUR, NOW(3), 0),
    (995120000000000026, 995100000000000001, 995000000000000001, 995000000000000003, 0, 0, NULL, '已收藏，准备按文中的四阶段重新检查我们的发布流程。', 8, 3, 1, NOW(3) - INTERVAL 12 HOUR, NOW(3), 0),
    (995120000000000027, 995100000000000001, 995000000000000001, 995000000000000001, 995120000000000003, 995120000000000003, 995000000000000004, '已有上传会继续完成，但会停止创建新的上传会话；超过宽限期的分片会记录状态并由后续任务接管。', 7, 4, 1, NOW(3) - INTERVAL 19 DAY, NOW(3), 0),
    (995120000000000028, 995100000000000001, 995000000000000001, 995000000000000001, 995120000000000006, 995120000000000006, 995000000000000003, '会保存载荷版本和处理器版本。重放入口先做兼容检查，无法兼容时转人工处理，不直接套用新逻辑。', 6, 3, 1, NOW(3) - INTERVAL 16 DAY, NOW(3), 0),
    (995120000000000029, 995100000000000001, 995000000000000001, 995000000000000002, 995120000000000006, 995120000000000028, 995000000000000001, '版本兼容检查很关键，这也能避免修复代码上线后把历史失败任务处理成另一种结果。', 5, 2, 1, NOW(3) - INTERVAL 15 DAY, NOW(3), 0)
ON DUPLICATE KEY UPDATE id = VALUES(id);

INSERT IGNORE INTO t_acceptance_data_batch_item (batch_code, entity_type, entity_id)
SELECT @batch_code, 'COMMENT', id
FROM t_int_comment
WHERE id BETWEEN 995120000000000001 AND 995120000000000029;

INSERT INTO t_interview_question
    (id, canonical_id, question_text, normalized_hash, answer_hint, exam_point, reference_answer,
     source_snippet, quality_reason, company, position, interview_round, difficulty, confidence,
     source_post_id, source_author_uid, status, appear_count, quality_score, create_time, update_time)
VALUES
    (995200000000000001, NULL, 'Java 服务平滑停机时，为什么要先改变就绪状态再关闭线程池？', SHA2('r9-question-001', 256), '从流量摘除、存量任务和存活检查差异回答。', 'Java 服务生命周期', '先让就绪检查失败，使负载均衡停止分发新流量，同时保持进程存活以完成已有请求和任务；随后关闭入口、等待存量任务并记录未完成项，最后退出进程。', '服务收到终止信号后分阶段停止接流量和处理任务。', '来源正文包含完整的工程时序和可验证验收标准。', NULL, '后端工程师', NULL, 'medium', 0.9600, 995100000000000001, 995000000000000001, 1, 8, 96, NOW(3) - INTERVAL 20 DAY, NOW(3)),
    (995200000000000002, NULL, '任务可能被重放时，业务幂等通常需要保存哪些关键标识？', SHA2('r9-question-002', 256), '业务唯一键、幂等键、载荷版本和处理阶段。', '任务重放与幂等', '至少保存业务唯一键、幂等键、载荷版本、处理器版本和已完成阶段；重放前先查询最终状态，避免重复写入或重复触发外部副作用。', '未完成任务记录业务键、幂等键和失败阶段。', '问题可从来源正文直接追溯，并能检验工程边界理解。', NULL, '后端工程师', NULL, 'hard', 0.9400, 995100000000000001, 995000000000000001, 1, 6, 94, NOW(3) - INTERVAL 19 DAY, NOW(3)),
    (995200000000000003, NULL, 'Redis 旁路缓存中，数据库更新成功但缓存删除失败时如何补偿？', SHA2('r9-question-003', 256), '删除重试、幂等、短过期和热点重建。', 'Redis 缓存一致性', '将删除失败写入可重试任务并携带幂等键；缓存设置合理过期时间，热点键可采用逻辑过期和互斥重建；对强一致流程必要时绕过缓存。', '提交数据库后删除缓存，删除失败进入重试队列。', '覆盖一致性、补偿和热点保护三个层次。', NULL, '后端工程师', NULL, 'medium', 0.9300, 995100000000000002, 995000000000000001, 1, 7, 93, NOW(3) - INTERVAL 18 DAY, NOW(3)),
    (995200000000000004, NULL, 'Spring 同类方法内部调用为什么可能让事务注解失效？', SHA2('r9-question-004', 256), '代理调用边界和 self-invocation。', 'Spring AOP 事务代理', '声明式事务通常由代理拦截外部方法调用；同一个对象内部直接调用不会经过代理，因此事务拦截器没有机会生效。可拆分 Bean、上移事务边界或使用显式事务。', '同类自调用绕过代理。', '高频概念与工程修复方式均可由来源正文验证。', NULL, '后端工程师', NULL, 'easy', 0.9200, 995100000000000003, 995000000000000001, 1, 9, 92, NOW(3) - INTERVAL 17 DAY, NOW(3)),
    (995200000000000005, NULL, 'Kafka 至少一次投递下，怎样避免重复消息产生重复业务结果？', SHA2('r9-question-005', 256), '业务唯一键、结果约束和外部副作用记录。', 'Kafka 消费幂等', '用业务唯一键或幂等表约束结果写入，把消费结果与幂等记录放在可保持一致的事务中；外部副作用单独记录阶段，消息再次到达时先返回已有结果或继续补偿。', '处理成功后、偏移量提交前重启会让消息再次到达。', '来源是完整故障复盘，能解释投递语义与业务责任。', NULL, '后端工程师', NULL, 'hard', 0.9500, 995100000000000004, 995000000000000001, 1, 8, 95, NOW(3) - INTERVAL 16 DAY, NOW(3)),
    (995200000000000006, NULL, '分析 MySQL 慢查询时，为什么不能只看一次 EXPLAIN？', SHA2('r9-question-006', 256), '真实参数分布、执行时资源竞争和扫描返回比例。', 'MySQL 性能诊断', '一次执行计划无法覆盖参数分布、缓存状态、锁等待、连接池排队和运行时资源竞争。应结合慢日志样本、扫描行数、返回行数、实际耗时和相同参数的优化前后对照。', '需要结合真实参数分布和运行时指标确认瓶颈。', '适合作为基础诊断题，答案边界清楚。', NULL, '后端工程师', NULL, 'easy', 0.9000, 995100000000000005, 995000000000000001, 1, 5, 90, NOW(3) - INTERVAL 15 DAY, NOW(3)),
    (995200000000000007, NULL, '进入新团队的第一个月，怎样选择适合主动推进的第一个问题？', SHA2('r9-question-007', 256), '先收集背景，再选择低风险、可验证、需要协作的小问题。', '团队协作与边界', '先了解目标、历史约束和关键协作者，确认问题确实存在；选择影响明确、范围小、容易回滚且能在短周期验证的问题，先提出观察和选项，而不是直接宣布完整改造方案。', '新成员需要在主动和理解历史之间找到边界。', '来源是具体职业场景，适合检验沟通判断。', NULL, '通用岗位', NULL, 'medium', 0.8800, 995100000000000008, 995000000000000002, 1, 4, 88, NOW(3) - INTERVAL 14 DAY, NOW(3)),
    (995200000000000008, NULL, '学习一个新概念时，怎样设计最小练习来暴露“只是记住术语”？', SHA2('r9-question-008', 256), '用自己的话解释，并在新情境中完成可观察任务。', '学习反馈设计', '先不用原文术语解释概念解决的问题和前提，再构造一个最小情境预测结果并验证；失败时记录属于概念、记忆、表达还是环境问题，再针对错误类型安排下一次练习。', '练习层要求尽早暴露不会，并对错误类型分类。', '来源给出了输入、练习、反馈和复习的完整闭环。', NULL, '通用岗位', NULL, 'medium', 0.9100, 995100000000000011, 995000000000000003, 1, 6, 91, NOW(3) - INTERVAL 13 DAY, NOW(3))
ON DUPLICATE KEY UPDATE id = VALUES(id);

